'use strict';
/* Original implementation informed by public OS-portfolio interaction patterns. */
const recentApps=[];
let notePage='about',projectPage=null,homePressTimer=null;
const originalPages={...pages};
const notes={
about:{title:'Hey, I’m Gaurav.',label:'About me',body:()=>originalPages.notes()},
work:{title:'How I work',label:'How I work',body:()=>`<p class="kicker">A FEW THINGS I COME BACK TO</p><h3>Make it real.</h3><p>I like taking an idea far enough that someone can actually try it. A product, a workflow, a script, an experiment.</p><p>FVI taught me that building something is only part of the job. Demand has to be tested too.</p><p>Content work taught me to connect the whole process: research, script, generation, stitching and the final video.</p><p>Team sports gave me another place to practise showing up, communicating and taking responsibility.</p><p><em>Still learning. Preferably by doing.</em></p>`},
journey:{title:'The road here',label:'The road here',body:()=>`<p class="kicker">SURAT → NIT SURAT → WHAT’S NEXT</p><h3>A different direction.</h3><img class="portrait-cover" src="assets/portrait.webp" alt="Gaurav outside SVNIT"><p>I studied Chemistry at NIT Surat, graduating in 2026. Over the last year, I deliberately started moving into tech.</p><p>That meant building with AI, trying product ideas, working on content, and getting comfortable learning as I went.</p><p>I chose to look beyond a conventional MNC campus offer. I want to work at a startup where I can own real problems and see the impact of the work.</p><button class="quick-open" data-open="contact">What’s next? Let’s talk →</button>`}
};
pages.notes=()=>`<nav class="note-tabs" aria-label="Notes">${Object.entries(notes).map(([id,n])=>`<button data-note="${id}" aria-pressed="${notePage===id}">${n.label}</button>`).join('')}</nav><div class="note-sheet">${notes[notePage].body()}</div><p class="note-signature">— Gaurav</p>`;
const projectItems=[{id:'fvi',name:'Follow Verified Investors',sub:'Product experiment · Next.js + Supabase',icon:'projects',status:'Built. Didn’t find market fit.'},{id:'athleteos',name:'AthleteOS',sub:'Personal health-data experiment',icon:'sports',status:'Unfinished. Plenty learned.'},{id:'msme',name:'MSME credit risk',sub:'Team analytics · Python + SQL + Power BI',icon:'resume',status:'1,700+ MSMEs in the analysis.'}];
const projectArticles=new DOMParser().parseFromString(originalPages.projects(),'text/html');
const projectBodies=[...projectArticles.querySelectorAll('article')].map(el=>el.outerHTML);
pages.projects=()=>{
 if(projectPage){const index=projectItems.findIndex(p=>p.id===projectPage);return `<div class="project-detail-actions"><button class="back-list" id="project-back">‹ All projects</button><button class="back-list" id="copy-project-link">Copy link ↗</button></div><div class="project-detail">${projectBodies[index]}</div><button class="quick-open" data-open="contact">Talk about this project →</button>`}
 return `<div class="project-header"><p class="kicker">THINGS I’VE BUILT & LEARNED FROM</p><h3>My work.</h3><p>Tap a project for the story behind it.</p></div><div class="ios-list">${projectItems.map((p,i)=>`<button class="project-row" data-project="${p.id}"><span class="project-mini project-mini-${i}">${svg(p.icon)}</span><span class="project-row-copy"><strong>${p.name}</strong><small>${p.sub}</small><em>${p.status}</em></span><span class="row-chevron">›</span></button>`).join('')}</div><div class="work-note"><span>THE COMMON THREAD</span><p>From an idea to something you can try.<br>Then learning what actually matters.</p></div>`;
};
const contactsBase=pages.contact;
pages.contact=()=>`<div class="contact-hero"><img src="assets/portrait.webp" alt="Gaurav Bihani"><h3>Gaurav Bihani</h3><p>Products · AI · Growth</p><span>Surat, India · NIT Surat ’26</span></div><div class="contact-actions"><a href="mailto:gauravbihanigb@gmail.com">${svg('mail')}<span>Email</span></a><a href="https://www.linkedin.com/in/gauravbihanii" target="_blank" rel="noopener noreferrer">${svg('linkedin')}<span>LinkedIn</span></a><button class="quick-view">${svg('resume')}<span>Quick view</span></button></div><article class="paper-card"><p>Open to startup roles across product, AI workflows, growth and operations.</p><div class="contact-row"><a href="mailto:gauravbihanigb@gmail.com">gauravbihanigb@gmail.com</a><button class="copy-button" id="copy-email">Copy</button></div><div class="contact-row"><span>GitHub</span>${ext('https://github.com/gau-rav0','gau-rav0')}</div><div class="contact-row"><span>X</span>${ext('https://x.com/gauravbihanii','@gauravbihanii')}</div></article>`;
const photosBase=pages.photos;
pages.photos=()=>`<div class="camera-roll-head"><h3>Camera Roll</h3><span>${photos.length} moments</span></div>${photosBase().replace('<p class="kicker">Camera roll / a few favourites</p><h3>Life, in between.</h3>','')}<p class="camera-footer">A little life, outside the screen.</p>`;
// OS overlays use the phone's geometry and remain inside its display.
const osPanel=document.createElement('section');osPanel.className='os-panel';osPanel.hidden=true;osPanel.setAttribute('role','dialog');osPanel.setAttribute('aria-modal','true');osPanel.setAttribute('aria-label','Search this iPhone');$('#screen').append(osPanel);
let overlayKind=null,overlayReturn=null;
function closeOS(){if(osPanel.hidden)return;osPanel.hidden=true;overlayKind=null;$('#home').inert=locked||Object.hasOwn(pages,currentApp());$('#app-panel').inert=locked;if(overlayReturn?.isConnected)overlayReturn.focus({preventScroll:true})}
function openOS(kind){if(locked)unlock();overlayReturn=document.activeElement;overlayKind=kind;$('#home').inert=true;$('#app-panel').inert=true;osPanel.hidden=false;osPanel.setAttribute('aria-label',kind==='search'?'Search this iPhone':'Recent apps');if(kind==='search'){osPanel.innerHTML=`<div class="os-searchbar"><label><span aria-hidden="true">⌕</span><input id="os-search" type="search" placeholder="Search Gaurav’s iPhone" aria-label="Search portfolio" autocomplete="off"></label><button data-os-close>Cancel</button></div><div class="os-scroll"><p class="search-prompt">What would you like to know?</p><div class="search-suggestions"><button data-query="What has he built?">What has he built?</button><button data-query="Show me his sports experience">Sports & leadership</button><button data-query="How can I contact him?">Let’s connect</button></div><div id="os-results" aria-live="polite"></div><p class="search-footnote">Searches the information in this portfolio.</p></div>`;searchPortfolio('');$('#os-search').focus({preventScroll:true})}else{const list=recentApps.length?recentApps:['notes','projects','videos','sports'];osPanel.innerHTML=`<div class="recents-title"><div><p>RIGHT WHERE YOU LEFT OFF</p><h3>Recent apps</h3></div><button data-os-close aria-label="Close recent apps">Done</button></div><div class="recent-list">${list.map(id=>{const def=appDefs.find(a=>a[0]===id);return `<button class="recent-app" data-os-open="${lastAppRoutes.get(id)||id}"><span class="icon-face" style="--top:${def[2]};--bottom:${def[3]}">${svg(id)}</span><span><strong>${def[1]}</strong><small>${appDescriptions[id]}</small></span><b>›</b></button>`}).join('')}</div><button class="recent-home" data-os-home>Back to Home screen</button>`;osPanel.querySelector('button').focus({preventScroll:true})}}
const appDescriptions={notes:'A little about Gaurav',projects:'Products, experiments and lessons',videos:'AI content & introduction',sports:'Teamwork and leadership',photos:'Life outside the screen',resume:'The one-page version',contact:'Start a conversation',settings:'Make yourself at home'};
const searchIndex=[
{id:'projects',title:'Projects & experiments',answer:'FVI, AthleteOS and MSME credit-risk analytics.',terms:'project projects build built product products fvi investor investors investment portfolio app apps athlete athleteos whoop samsung risk msme python sql data dashboard code coding technical tech'},
{id:'notes',title:'About Gaurav',answer:'NIT Surat Chemistry graduate, moving into products, AI and growth.',terms:'about gaurav who introduction bio background chemistry education nit svnit surat graduate college journey work style learning startup startups hire hiring why role growth founder office'},
{id:'videos',title:'AI content production',answer:'Work with Sahil Khanna / Litmus by Lapaas; reported 50K+ views on a contributed video.',terms:'video videos intro introduction content sahil khanna litmus lapaas youtube views 50k fifty claude higgsfield ai automation workflows script scripts'},
{id:'sports',title:'Sports & leadership',answer:'SVNIT basketball vice-captaincy, powerlifting team leadership and sponsorship work.',terms:'sports sport basketball football powerlifting gym leadership leader lead captain vice teamwork team events pregrad sparsh red bull decathlon'},
{id:'contact',title:'Contact Gaurav',answer:'Email, LinkedIn, GitHub and X. Say hello.',terms:'contact email mail reach talk chat connect connection linkedin github twitter x hire hiring message phone number available availability'},
{id:'resume',title:'Résumé',answer:'Read or download the one-page résumé.',terms:'resume résumé cv download experience qualifications credentials pdf job jobs application'},
{id:'photos',title:'Photos',answer:'Travel, college and time on the field.',terms:'photo photos picture pictures travel mountains river beach life hobbies interests camera gallery'},
{id:'settings',title:'Settings',answer:'Wallpapers, animation, automatic rotation and locking.',terms:'settings setting wallpaper wallpapers background change classic lock locking screen animation animations auto rotate rotation theme'}];
function searchPortfolio(query){const tokens=query.toLowerCase().replace(/[^a-z0-9é ]/g,' ').split(/\s+/).filter(t=>t.length>1&&!['show','tell','does','what','his','her','the','you','and','has','how','can','about','me','he','is','to','of','be','want','this','that','with','for','him','please','who','are','would','like'].includes(t));let hits=searchIndex.map(item=>({...item,score:tokens.reduce((n,t)=>n+(item.terms.split(' ').includes(t)?2:0)+(item.title.toLowerCase().includes(t)?1:0),0)})).filter(item=>!query.trim()||item.score>0).sort((a,b)=>b.score-a.score);$('#os-results').innerHTML=hits.length?`<p class="search-section-label">${query.trim()?'MATCHES':'ON THIS IPHONE'}</p>${hits.map(item=>`<button class="search-result" data-os-open="${item.id}"><span class="search-mini">${svg(item.id)}</span><span><strong>${item.title}</strong><small>${item.answer}</small></span><b>›</b></button>`).join('')}`:`<div class="search-empty"><strong>No match yet.</strong><p>Try “projects”, “AI content”, “sports” or “contact”.</p><button data-query="contact">Ask Gaurav directly →</button></div>`;}
const originalRender=render;
const appScrollPositions=new Map();const lastAppRoutes=new Map();let previousApp='',appTransitionTimer=null;
const originalShowPhoto=showPhoto;
showPhoto=function(index){if(!Number.isInteger(index)||!photos[index])return;const route='photos/'+photos[index][0];if(location.hash.slice(1)===route)originalShowPhoto(index);else location.hash=route};
render=function(){const id=currentApp();const route=location.hash.slice(1);const detail=route.split('/')[1];projectPage=id==='projects'&&projectItems.some(p=>p.id===detail)?detail:null;if(id==='notes')notePage=Object.hasOwn(notes,detail)?detail:'about';if(!osPanel.hidden)closeOS();if(previousApp&&previousApp!==id)appScrollPositions.set(previousApp,$('#app-content').scrollTop);originalRender();if(previousApp!==id)$('#app-content').scrollTop=appScrollPositions.get(id)||0;previousApp=id;$('#app-content').dataset.app=id;const nested=Boolean(detail)&&['projects','notes','photos'].includes(id);$('#back').textContent=nested?'‹ '+appDefs.find(a=>a[0]===id)[1]:'‹ Home';$('#back').onclick=()=>nested?openApp(id):home();if(id==='photos'&&detail){const photo=photos.findIndex(p=>p[0]===detail);if(photo>=0)originalShowPhoto(photo)}if(Object.hasOwn(pages,id)){lastAppRoutes.set(id,route);const index=recentApps.indexOf(id);if(index>=0)recentApps.splice(index,1);recentApps.unshift(id);recentApps.splice(8);clearTimeout(appTransitionTimer);$('#app-panel').classList.remove('app-reenter');if(motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches){void $('#app-panel').offsetWidth;$('#app-panel').classList.add('app-reenter');appTransitionTimer=setTimeout(()=>$('#app-panel').classList.remove('app-reenter'),300)}}document.title=projectPage?`${projectItems.find(p=>p.id===projectPage).name} — Gaurav Bihani`:Object.hasOwn(pages,id)?`${appDefs.find(a=>a[0]===id)[1]} — Gaurav’s iPhone`:'Gaurav Bihani — Products, AI & Growth'};
const originalOpen=openApp;
openApp=function(route){const id=route.split('/')[0];if(!Object.hasOwn(pages,id))return;closeOS();const icon=document.querySelector(`#apps [data-open="${id}"]`);if(icon){const r=icon.getBoundingClientRect(),s=$('#screen').getBoundingClientRect();$('#app-panel').style.transformOrigin=`${r.left+r.width/2-s.left}px ${r.top+r.height/2-s.top}px`}originalOpen(route)};
// Existing hash listener keeps back/forward behavior; apply enhanced rendering on routes.
const originalLockPhone=lockPhone;lockPhone=function(){closeOS();originalLockPhone()};$('#lock-phone').onclick=lockPhone;
$('#spotlight-button').onclick=()=>openOS('search');$('#switch-apps').onclick=()=>openOS('recent');
$('#home-button').onclick=()=>{clearTimeout(homePressTimer);homePressTimer=setTimeout(()=>{if(locked)$('#unlock-slider').focus({preventScroll:true});else if(!osPanel.hidden)closeOS();else home()},220)};
$('#home-button').ondblclick=()=>{clearTimeout(homePressTimer);if(!locked)openOS('recent')};
$('#sleep-button').onclick=()=>{closeOS();if(locked)$('#unlock-slider').focus({preventScroll:true});else lockPhone()};
osPanel.addEventListener('input',e=>{if(e.target.id==='os-search')searchPortfolio(e.target.value)});
osPanel.addEventListener('click',e=>{const target=e.target.closest('[data-os-close],[data-os-open],[data-query],[data-os-home]');if(!target)return;if(target.hasAttribute('data-os-close'))closeOS();else if(target.dataset.osOpen)openApp(target.dataset.osOpen);else if(target.dataset.query){$('#os-search').value=target.dataset.query;searchPortfolio(target.dataset.query);$('#os-search').focus({preventScroll:true})}else{closeOS();home()}});
osPanel.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();closeOS()}if(e.key==='Enter'&&e.target.id==='os-search'){const first=osPanel.querySelector('[data-os-open]');if(first)openApp(first.dataset.osOpen)}if(e.key==='Tab'){const targets=[...osPanel.querySelectorAll('input,button,a')].filter(el=>!el.disabled);const first=targets[0],last=targets.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
document.addEventListener('click',e=>{const n=e.target.closest('[data-note]');if(n){openApp('notes/'+n.dataset.note);return}const p=e.target.closest('[data-project]');if(p){openApp('projects/'+p.dataset.project);return}if(e.target.closest('#project-back')){openApp('projects');return}if(e.target.closest('#copy-project-link'))copyProjectLink(e.target.closest('#copy-project-link'));if(e.target.closest('[data-photo-back]'))openApp('photos')});
// Pull down on the home-screen background to open search; vertical app scrolling stays native.
let gesture=null;$('#home').addEventListener('pointerdown',e=>{if(e.target.closest('button,a'))return;gesture={x:e.clientX,y:e.clientY}});$('#home').addEventListener('pointerup',e=>{if(!gesture)return;if(e.clientY-gesture.y>65&&Math.abs(e.clientX-gesture.x)<45)openOS('search');gesture=null});$('#home').addEventListener('pointercancel',()=>gesture=null);
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openOS('search')}});
render();

async function copyProjectLink(button){const link=new URL(location.href);link.hash='projects/'+projectPage;try{await navigator.clipboard.writeText(link.href);button.textContent='Copied ✓';button.setAttribute('aria-live','polite')}catch{const area=document.createElement('input');area.className='share-link-fallback';area.value=link.href;area.readOnly=true;area.setAttribute('aria-label','Project link — select and copy');button.after(area);area.focus();area.select();button.textContent='Select link below'}}
